def _mk(aid, name, cls, area, twin, crit="B", mfr="", model="", year=2022, **kw):
    a = {"id": aid, "name": name, "cls": cls, "cls_name": CLASS_NAME[cls], "area": area, "twin": twin, "crit": crit,
         "mfr": mfr, "model": model, "year": year, "linear": False}
    a.update(kw)
    a["tasks"] = [{"code": t[0], "name": t[1], "type": t[2], "every": t[3], "dur_h": t[4], "crew": t[5], "n": t[6], "cost": t[7]} for t in TASKS[cls]]
    return a


def _approach_pts():
    e = G.GRAPH.edges[("J1", "CR")]
    n = int(min(e["len"], 260.0) // 10)
    return [G.polyline_at(e["pts"], e["len"] - 10.0 * i)[0] for i in range(n, -1, -1)]


