    A.append(_mk("CM-1", "Электродвигатель привода ККД 1500 кВт, 6 кВ", "motor", "Обогатительная фабрика / Дробление", "cr-motor", "A", "по паспорту класса", "синхронный 1500 кВт, 6 кВ", 2017, src=("crush", "motor")))
    A.append(_mk("DS-1", "Система пылеподавления ККД (форсунки тумана, насосная станция)", "dustsup", "Обогатительная фабрика / Дробление", "cr-dust", "C", year=2021, src=("crush", "dust")))
    for k in (1, 2):
        A.append(_mk(f"BAY-{k}", f"Место разгрузки №{k}: площадка, колёсоотбойный вал, светофор", "dumpbay", "Обогатительная фабрика / Дробление", f"cr-bay-{k}", "B", year=2018))
    A.append(_mk("RD-CR", "Подъездная дорога к ККД (последние 260 м)", "road", "Обогатительная фабрика / Дробление", "cr-approach", "A", year=2018,
                 linear=True, length_m=260.0, material="щебёночное покрытие, полотно 24 м", pts=[[round(p[0], 1), round(p[1], 1), 0.0] for p in _approach_pts()]))
    A.append(_mk("ML-1", "МПСИ 11,6 × 6,1 м (полусамоизмельчение)", "mill", "Обогатительная фабрика / Измельчение", "mill-sag", "A", "по паспорту класса", "16 МВт", 2017, src=("grind", "liner_sag")))
    A.append(_mk("ML-2", "МШЦ 7,9 × 13,6 м с гидроциклонами", "mill", "Обогатительная фабрика / Измельчение", "mill-ball", "A", "по паспорту класса", "16 МВт", 2017, src=("grind", "liner_ball")))
    A.append(_mk("FL-1", "Флотация: основная, контрольная и перечистные", "plant", "Обогатительная фабрика", "flotation", "A", year=2017, src=("calendar",)))
    for k, (fid, name) in enumerate((("feeder-pit", "Фидер 6 кВ карьера"), ("feeder-crusher", "Фидер ККД и конвейеров"), ("feeder-mill", "Фидер мельниц"),
                                     ("feeder-flot", "Фидер флотации и вспомогательных"))):
        A.append(_mk(f"FD-{k + 1}", name, "feeder", "Энергоснабжение", fid, "B", year=2017))
    A.append(_mk("GPP-1", "ГПП-110/6 кВ: два трансформатора 40 МВА", "gpp", "Энергоснабжение / ГПП", "power", "A", "по паспорту класса", "2 × ТДН-40000/110", 2017))
    for k in (1, 2):
        A.append(_mk(f"TR-T{k}", f"Силовой трансформатор Т{k} ТДН-40000/110/6", "gpp", "Энергоснабжение / ГПП", f"gpp-t{k}", "A", "по паспорту класса", "40 МВА, 110/6,3 кВ, РПН", 2017, src=("gpp", f"T{k}")))
        A.append(_mk(f"HV-L{k}", f"Воздушная линия 110 кВ №{k} (ввод)", "cable", "Энергоснабжение / ГПП", f"gpp-line-{k}", "A", year=2016, src=("gpp", f"L{k}"), linear=True, length_m=14200.0,
                     material="провод АС-240", pts=[[round(G.GRAPH.nodes["CR"][0] + 220.0, 1), round(G.GRAPH.nodes["CR"][1] + 170.0, 1), 0.0], [round(G.GRAPH.nodes["CR"][0] - 900.0, 1), round(G.GRAPH.nodes["CR"][1] + 1500.0 + 40 * k, 1), 0.0]]))
        A.append(_mk(f"KRU-{k}", f"Секция {k} КРУ 6 кВ", "feeder", "Энергоснабжение / ГПП", f"gpp-bus-{k}", "A", year=2017))
        A.append(_mk(f"CP-{k}", f"Конденсаторная установка №{k}, 6 Мвар", "capbank", "Энергоснабжение / ГПП", f"gpp-cap-{k}", "C", year=2019, src=("gpp", f"C{k}")))
    A.append(_mk("KRU-SV", "Секционный выключатель КРУ 6 кВ", "feeder", "Энергоснабжение / ГПП", "gpp-tie", "B", year=2017, src=("gpp", "SV")))
    # --- дороги — линейные активы
    for seg, title in G.SEGMENTS.items():
        pts, ln = [], 0.0
        for (a, b), e in G.GRAPH.edges.items():
            if e["seg"] == seg and a < b:
                pts.append([[round(p[0], 1), round(p[1], 1), round(p[2], 1)] for p in e["pts"]])
                ln += e["len"]
        A.append(_mk(f"RD-{seg}", title, "road", "Карьер / Дороги", f"road-{seg}", "B", year=2018, linear=True, length_m=round(ln, 0), material="щебёночное покрытие, полотно 22–24 м",
                     pts_multi=pts))
    # Existing functional locations stay valid; independently maintained parts get their own twins.
    by_id={a['id']:a for a in A}
    for spec in m.equipment_specs:
        legacy=spec['parameters'].get('legacy_asset')
        a=by_id.get(legacy)
        if a:a['twin']=spec['twin']
        else:
            a=_mk(spec['id'],spec['name'],spec['cls'],CR_AREA.get(spec['site'],spec['site']),spec['twin'],'B',model=spec['parameter_basis'],year=None,src=('equipment',spec['twin']))
            A.append(a)
        x,y,z=EQ.world(m,spec)
        a.update(parent_twin=spec['parent'],site=spec['site'],x=x,y=y,z=z,rated_kw=spec['rated_kw'],parameters=spec['parameters'],parameter_basis=spec['parameter_basis'])
    return A

